3. Определите функцию, которая считывает файл построчно и возвращает вектор строк:

```cpp
std::vector<std::string> read_file(const std::string& filename) {
    std::vector<std::string> lines;
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return lines;
    }
    std::string line;
    while (getline(file, line)) {
        lines.push_back(line);
    }
    file.close();
    return lines;
}
```

4. Определите функцию, которая считает количество вхождений слова в векторе строк:

```cpp
int count_word_occurrences(const std::vector<std::string>& lines, const std::string& word) {
    int count = 0;
    std::transform(lines.begin(), lines.end(), std::back_inserter(std::vector<std::string>(lines.size())),
                   [&word](const std::string& line) {
                       std::size_t pos = 0;
                       while ((pos = line.find(word, pos)) != std::string::npos) {
                           ++count;
                           pos += word.length();
                       }
                       return line;
                   });
    return count;
}
```

